contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Single public entry: take an initial deposit amount to establish credit
    function run(uint depositAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount) + (0)); require(depositAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= depositAmount);

        // Establish credit for this contract in C by depositing depositAmount (possibly zero)
        c.deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;

        // Record balances before first withdrawAll
        uint beforeCTest = address(c).balance;
        uint beforeThis = address(this).balance;

        // Call withdrawAll and record whether it reverted
        bool firstReverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            firstReverted = true;
        } else {
            firstReverted = false;
        }

        // Record balances after first withdrawAll
        uint afterFirstCTest = address(c).balance;
        uint afterFirstThis = address(this).balance;

        // Make a zero-value deposit as a probe (top-level state-changing call)
        c.deposit{value: 0}(); if (__ESBMC_reverted()) return;

        // Record balance before second withdrawAll
        uint beforeSecondThis = address(this).balance;

        // Call withdrawAll a second time and record whether it reverted
        bool secondReverted;
        c.withdrawAll(); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            secondReverted = true;
        } else {
            secondReverted = false;
        }

        // Record balance after second withdrawAll
        uint afterSecondThis = address(this).balance;

        // General rule asserted:
        // If the first withdrawAll succeeded, then the second withdrawAll (after a zero deposit) must not transfer any Ether to this contract and must not revert.
        // Also assert that when first succeeded, C's balance did not increase (it stayed the same or decreased).
        assert(firstReverted || (secondReverted == false && afterSecondThis == beforeSecondThis && afterFirstCTest <= beforeCTest));
    }

    receive() external payable { }
}

